324	    /**
325	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
326	     * {@code telephone} is missing or blank (including whitespace-only values that Bean Validation
327	     * does not catch). The names of all offending fields are collected so the caller receives a
328	     * 400 response whose {@code errors} array lists each one.
329	     */
330	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
331	        List<String> missingFields = new ArrayList<>();
332	        if (isBlank(ownerFieldsDto.getFirstName())) {
333	            missingFields.add("firstName");
334	        }
335	        if (isBlank(ownerFieldsDto.getLastName())) {
336	            missingFields.add("lastName");
337	        }
338	        if (isBlank(ownerFieldsDto.getAddress())) {
339	            missingFields.add("address");
340	        }
341	        if (isBlank(ownerFieldsDto.getCity())) {
342	            missingFields.add("city");
343	        }
344	        if (isBlank(ownerFieldsDto.getTelephone())) {
345	            missingFields.add("telephone");
346	        }
347	        if (!missingFields.isEmpty()) {
348	            throw new InvalidOwnerFieldsException(missingFields);
349	        }
350	    }
351	
352	    private static boolean isBlank(String value) {
353	        return value == null || value.trim().isEmpty();
354	    }
355	
356	    /**
357	     * Normalizes an owner's address on create, supporting both the structured form
358	     * ({@code addressLine1} plus optional {@code addressLine2}) and the flat {@code address} form kept
359	     * for backward compatibility. Whichever fields are supplied are canonicalized in place - trimmed,
360	     * internal whitespace runs collapsed to a single space, upper-cased and common street-type
361	     * abbreviations expanded as whole tokens ({@code ST}->{@code STREET}, {@code RD}->{@code ROAD},
362	     * {@code AVE}->{@code AVENUE}). The canonical {@code addressLine1}/{@code addressLine2} are written
363	     * back, and the composed {@code address} - the normalized {@code addressLine1} with a single space
364	     * and the normalized {@code addressLine2} appended when present, falling back to the normalized
365	     * flat {@code address} when no structured line is given - is written onto the request so it is what
366	     * gets validated, compared, stored and returned. Running before the required-field check means an
367	     * address that is blank in both forms after normalization is rejected like a missing one.
368	     */
369	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
370	        String line1 = canonicalAddress(ownerFieldsDto.getAddressLine1());
371	        String line2 = canonicalAddress(ownerFieldsDto.getAddressLine2());
372	        String flat = canonicalAddress(ownerFieldsDto.getAddress());
373	        ownerFieldsDto.setAddressLine1(line1);
374	        ownerFieldsDto.setAddressLine2(line2);
375	        ownerFieldsDto.setAddress(composeAddress(line1, line2, flat));
376	    }
377	
378	    /**
379	     * Composes the effective address, preferring the structured form: when {@code line1} is present
380	     * (non-blank) the result is {@code line1}, with a single space and {@code line2} appended when
381	     * {@code line2} is present; otherwise the flat {@code address} is used. All three inputs are
382	     * expected to be already canonicalized. Returns the flat value (which may be {@code null} or blank,
383	     * left for the required-field check to reject) when no structured line is supplied.
384	     */
385	    private static String composeAddress(String line1, String line2, String flat) {
386	        if (line1 != null && !line1.isBlank()) {
387	            if (line2 != null && !line2.isBlank()) {
388	                return line1 + " " + line2;
389	            }
390	            return line1;
391	        }
392	        return flat;
393	    }
394	
395	    /**
396	     * Returns the canonical form of an address: trimmed, internal whitespace runs collapsed to a
397	     * single space, upper-cased, with common street-type abbreviations expanded as whole tokens. A
398	     * {@code null} value returns {@code null}. The transform is idempotent, so an already-canonical
399	     * address is returned unchanged, making it safe to apply to stored values during comparison.
400	     */
401	    private static String canonicalAddress(String address) {
402	        if (address == null) {
403	            return null;
404	        }
405	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
406	        if (collapsed.isEmpty()) {
407	            return "";
408	        }
409	        String[] tokens = collapsed.split(" ");
410	        StringBuilder sb = new StringBuilder(collapsed.length());
411	        for (int i = 0; i < tokens.length; i++) {
412	            if (i > 0) {
413	                sb.append(' ');
414	            }
415	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
416	        }
417	        return sb.toString();
418	    }
419	
420	    /**
421	     * Normalizes an owner's {@code telephone} on create into E.164 form. A leading {@code '+'} and
422	     * the country code that follows it are kept; otherwise the country code {@code '+61'} is assumed
423	     * and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes and
424	     * brackets are stripped. The result must have 8 to 15 digits after the {@code '+'}, and when the
425	     * country code is one whose national-number length is known ({@code '+61'} => 9 national digits,
426	     * {@code '+1'} => 10) the national number must have exactly that many digits. The E.164 string is
427	     * written back onto the request so it is what gets stored and returned. Any value that cannot
428	     * form a valid E.164 number is rejected with a 400 response whose {@code errors} array names
429	     * {@code telephone}.
430	     */
431	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
432	        ownerFieldsDto.setTelephone(toE164(ownerFieldsDto.getTelephone()));
433	    }
434	
435	    /**
436	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
437	     * (400) naming {@code telephone} when it cannot form a valid number.
438	     */
439	    private static String toE164(String telephone) {
440	        if (telephone == null) {
441	            throw new InvalidOwnerFieldsException(List.of("telephone"));
442	        }
443	        boolean hasCountryCode = telephone.trim().startsWith("+");
444	        String digits = telephone.replaceAll("\\D", "");
445	        String countryCode;
446	        String national;
447	        if (hasCountryCode) {
448	            countryCode = matchCountryCode(digits);
449	            national = digits;
450	        } else {
451	            countryCode = "61";
452	            if (digits.startsWith("0")) {
453	                digits = digits.substring(1);
454	            }
455	            national = "61" + digits;
456	        }
457	        if (!national.matches("[0-9]{8,15}")) {
458	            throw new InvalidOwnerFieldsException(List.of("telephone"));
459	        }
460	        if (countryCode != null) {
461	            Integer requiredLength = COUNTRY_NATIONAL_LENGTH.get(countryCode);
462	            if (requiredLength != null
463	                && national.length() - countryCode.length() != requiredLength) {
464	                throw new InvalidOwnerFieldsException(List.of("telephone"));
465	            }
466	        }
467	        return "+" + national;
468	    }
469	
470	    /**
471	     * Returns the longest known E.164 country code (a key of {@link #COUNTRY_NATIONAL_LENGTH}) that
472	     * the given country-code-prefixed digit string starts with, or {@code null} when none is known so
473	     * the number is not length-checked against a country.
474	     */
475	    private static String matchCountryCode(String digits) {
476	        return COUNTRY_NATIONAL_LENGTH.keySet().stream()
477	            .filter(digits::startsWith)
478	            .max(Comparator.comparingInt(String::length))
479	            .orElse(null);
480	    }
481	
482	    /**
483	     * Rejects creating an owner that duplicates an existing one, either as a household duplicate or
484	     * as an exact identity duplicate. The household is now keyed on the computed {@code householdId}
485	     * (a deterministic function of the normalized last name and postcode, see
486	     * {@link #computeHouseholdId}), so any existing owner already carrying the same {@code householdId}
487	     * belongs to the same household and makes the new owner a household duplicate. Independently, an
488	     * exact match on the derived {@code identityKey} - {@code normalizedTelephone + '|' + (email or
489	     * empty) + '|' + (householdId or empty)} - is also a duplicate; this still catches owners with no
490	     * postcode (and therefore no household) that share a telephone and email. Both checks are a 409.
491	     *
492	     * <p>The {@code sharesHousehold} flag bypasses the entire duplicate block: a request that opts in
493	     * is allowed through even when it lands in an existing household, so it is created as a declared
494	     * household member rather than rejected. The incoming telephone and email have already been
495	     * normalized by {@link #normalizeTelephone} and {@link #normalizeEmail}; each existing owner's key
496	     * is derived the same way before comparison. A match results in a 409 response naming
497	     * {@code identityKey}.
498	     */
499	    private void rejectDuplicate(OwnerFieldsDto ownerFieldsDto, String householdId) {
500	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
501	            return;
502	        }
503	        String identityKey = identityKey(ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
504	        for (Owner existing : this.clinicService.findAllOwners()) {
505	            boolean householdDuplicate = householdId != null && householdId.equals(existing.getHouseholdId());
506	            if (householdDuplicate || identityKey.equals(existingIdentityKey(existing))) {
507	                throw new DuplicateOwnerIdentityException(identityKey);
508	            }
509	        }
510	    }
511	
512	    /**
513	     * Builds an {@code identityKey} from its three parts: {@code telephone + '|' + email + '|' +
514	     * householdId}, with a {@code null} part contributing the empty string. The telephone and email
515	     * are expected to already be in their normalized (E.164, lower-cased) forms.
516	     */
517	    private static String identityKey(String telephone, String email, String householdId) {
518	        return orEmpty(telephone) + "|" + orEmpty(email) + "|" + orEmpty(householdId);
519	    }
520	
521	    /**
522	     * Derives an already-stored owner's {@code identityKey} for duplicate comparison: the stored
523	     * telephone is converted to E.164 form (or the empty string when it cannot form a valid number),
524	     * the stored email is lower-cased, and the stored household id is used as-is.
525	     */
526	    private static String existingIdentityKey(Owner existing) {
527	        String telephone = orEmpty(normalizeExisting(existing.getTelephone()));
528	        String email = existing.getEmail() == null ? "" : existing.getEmail().toLowerCase(Locale.ROOT);
529	        return identityKey(telephone, email, existing.getHouseholdId());
530	    }
531	
532	    private static String orEmpty(String value) {
533	        return value == null ? "" : value;
534	    }
535	
536	    /**
537	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, or {@code null}
538	     * when the stored value cannot form a valid E.164 number (so it never matches an incoming one).
539	     */
540	    private static String normalizeExisting(String telephone) {
541	        try {
542	            return toE164(telephone);
543	        } catch (InvalidOwnerFieldsException ex) {
544	            return null;
545	        }
546	    }
547	
548	    /**
549	     * Rejects creating an owner in a city that has reached capacity: a city that already contains
550	     * {@value #MAX_OWNERS_PER_CITY} or more owners cannot take another one. Existing owners are
551	     * counted with a case-insensitive match on {@code city}, the same way {@link #assignCustomerCode}
552	     * groups a city. A city at or over the limit results in a 409 response naming {@code city}.
553	     */
554	    private void rejectCityAtCapacity(OwnerFieldsDto ownerFieldsDto) {
555	        String city = ownerFieldsDto.getCity();
556	        int count = 0;
557	        for (Owner existing : this.clinicService.findAllOwners()) {
558	            if (city.equalsIgnoreCase(existing.getCity())) {
559	                count++;
560	            }
561	        }
562	        if (count >= MAX_OWNERS_PER_CITY) {
563	            throw new OwnerCityAtCapacityException(city);
564	        }
565	    }
566	
567	    /**
568	     * Rejects creating an owner once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the
569	     * given adjusted business-day {@code registrationDate}, counted by an exact match. The date has
570	     * already been resolved and rolled forward off a weekend by {@link #resolveRegistrationDate}, so
571	     * the limit is enforced per business day. A day at or over the limit results in a 429 response.
572	     */
573	    private void rejectDailyLimitReached(LocalDate registrationDate) {
574	        int count = 0;
575	        for (Owner existing : this.clinicService.findAllOwners()) {
576	            if (registrationDate.equals(existing.getRegistrationDate())) {
577	                count++;
578	            }
579	        }
580	        if (count >= MAX_OWNERS_PER_DAY) {
581	            throw new DailyOwnerLimitReachedException(registrationDate);
582	        }
583	    }
584	
585	    /**
586	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and
587	     * trailing whitespace is trimmed, internal runs of whitespace are collapsed to a single space and
588	     * the result is lower-cased. A {@code null} value normalizes to the empty string.
589	     */
590	    private static String normalizeForComparison(String value) {
591	        if (value == null) {
592	            return "";
593	        }
594	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
595	    }
596	
597	    /**
598	     * Normalizes an owner's optional {@code email}. The field may be omitted entirely, but when a
599	     * value is present it must be a syntactically valid address; the trimmed value is lower-cased and
600	     * written back onto the request so that is what gets stored and returned. A present but invalid
601	     * address is rejected with a 400 response whose {@code errors} array names {@code email}.
602	     */
603	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
604	        String email = ownerFieldsDto.getEmail();
605	        if (email == null) {
606	            return;
607	        }
608	        String trimmed = email.trim();
609	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
610	            throw new InvalidOwnerFieldsException(List.of("email"));
611	        }
612	        String normalized = trimmed.toLowerCase(Locale.ROOT);
613	        String domain = normalized.substring(normalized.indexOf('@') + 1);
614	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
615	            throw new InvalidOwnerFieldsException(List.of("email"));
616	        }
617	        ownerFieldsDto.setEmail(normalized);
618	    }
619	
620	    /**
621	     * Validates an owner's optional {@code postcode} on create. The field may be omitted entirely
622	     * (so an owner created without a postcode stays accepted), but when a value is present it must be
623	     * exactly 4 digits and valid for the region the owner's {@code city} derives to: NSW 2000-2099,
624	     * VIC 3000-3099, QLD 4000-4099. A city with no known region accepts any 4-digit postcode. A
625	     * present postcode that is malformed or out of range for the city's region is rejected with a 400
626	     * response whose {@code errors} array names {@code postcode}. A valid value is left on the request
627	     * as-is so it is stored and returned.
628	     */
629	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
630	        String postcode = ownerFieldsDto.getPostcode();
631	        if (postcode == null) {
632	            return;
633	        }
634	        if (!postcode.matches("[0-9]{4}")) {
635	            throw new InvalidOwnerFieldsException(List.of("postcode"));
636	        }
637	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.derive(ownerFieldsDto.getCity()));
638	        if (range != null) {
639	            int value = Integer.parseInt(postcode);
640	            if (value < range[0] || value > range[1]) {
641	                throw new InvalidOwnerFieldsException(List.of("postcode"));
642	            }
643	        }
644	    }
645	
646	    /**
647	     * Resolves an owner's effective {@code registrationDate} on create and rolls it onto a business
648	     * day. When the caller supplies no value it defaults to the server's current date; a value
649	     * provided in the request is kept. A supplied value later than the server's current date is
650	     * rejected with a 400 response whose {@code errors} array names {@code registrationDate}. The
651	     * effective date, whether supplied or defaulted, must fall on a business day: a Saturday or
652	     * Sunday is rolled forward to the following Monday. The adjusted date is written back onto the
653	     * request so it is what gets stored and returned (in ISO {@code YYYY-MM-DD} format) and what
654	     * every value derived from the registration date is based on.
655	     */
656	    private void resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
657	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
658	        if (effective == null) {
659	            effective = LocalDate.now();
660	        }
661	        else if (effective.isAfter(LocalDate.now())) {
662	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
663	        }
664	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
665	    }
666	
667	    /**
668	     * Rolls a date forward onto a business day: a Saturday or Sunday is advanced to the following
669	     * Monday; a weekday is returned unchanged.
670	     */
671	    private static LocalDate toBusinessDay(LocalDate date) {
672	        return switch (date.getDayOfWeek()) {
673	            case SATURDAY -> date.plusDays(2);
674	            case SUNDAY -> date.plusDays(1);
675	            default -> date;
676	        };
677	    }
678	
679	    /**
680	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<REGION>-<HASH8>'} where
681	     * {@code REGION} is the region the owner's identity derives to from its postcode (falling back to
682	     * the city table when the postcode is absent or in no known range) and {@code HASH8} is the first
683	     * eight upper-case hex characters of the SHA-256 digest of the normalized telephone concatenated
684	     * with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The telephone has already been normalized to
685	     * E.164 form by {@link #normalizeTelephone}. There is no per-city sequence: the identity is a
686	     * pure function of region, telephone and last name.
687	     */
688	    private void assignCustomerCode(Owner owner) {
689	        String region = OwnerLocality.derive(owner.getCity(), owner.getPostcode());
690	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName(), 8);
691	        owner.setCustomerCode(deduplicateCustomerCode(region + "-" + hash8));
692	    }
693	
694	    /**
695	     * Returns {@code customerCode} unchanged when no existing owner already carries it; otherwise
696	     * appends {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a value not held by
697	     * any existing owner. Compared against the pre-existing owners, so the returned code is unique
698	     * among them.
699	     */
700	    private String deduplicateCustomerCode(String customerCode) {
701	        Set<String> existing = new HashSet<>();
702	        for (Owner owner : this.clinicService.findAllOwners()) {
703	            if (owner.getCustomerCode() != null) {
704	                existing.add(owner.getCustomerCode());
705	            }
706	        }
707	        if (!existing.contains(customerCode)) {
708	            return customerCode;
709	        }
710	        int n = 2;
711	        while (existing.contains(customerCode + "-" + n)) {
712	            n++;
713	        }
714	        return customerCode + "-" + n;
715	    }
716	
717	    /**
718	     * Assigns the owner's {@code membershipNumber} on create, formatted
719	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
720	     * {@code registrationDate} year (e.g. {@code 'NSW-1A2B3C4D-M26'}). Assigned after
721	     * {@link #assignCustomerCode} and once {@code registrationDate} has been defaulted, so both
722	     * inputs are present.
723	     */
724	    private void assignMembershipNumber(Owner owner) {
725	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
726	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
727	    }
728	
729	    /**
730	     * Assigns the new owner's {@code namesakeCount} on create: the number of owners that already
731	     * exist sharing the same {@code firstName} and {@code lastName}, compared case-insensitively.
732	     * Computed before the new owner is persisted, so it counts only the pre-existing owners.
733	     */
734	    private void assignNamesakeCount(Owner owner) {
735	        String firstName = owner.getFirstName();
736	        String lastName = owner.getLastName();
737	        int count = 0;
738	        for (Owner existing : this.clinicService.findAllOwners()) {
739	            if (firstName.equalsIgnoreCase(existing.getFirstName())
740	                && lastName.equalsIgnoreCase(existing.getLastName())) {
741	                count++;
742	            }
743	        }
744	        owner.setNamesakeCount(count);
745	    }
746	
747	    /**
748	     * Assigns the new owner's {@code membershipPoints} and derived {@code membershipLevel} on create.
749	     * Points start at 0 and accrue: plus 2 when an email is present, plus 1 when {@code namesakeCount}
750	     * is 0, plus 2 for a household of 3 or more members, and plus 3 for tenure exceeding
751	     * {@value #TENURE_LEVEL_THRESHOLD_DAYS} days. The points are then mapped to a level of 1 (0-1
752	     * points), 2 (2-3), 3 (4-5), or 4 (6 or more). Runs after {@link #assignNamesakeCount} and
753	     * {@link #assignHouseholdMembership} so those counts are settled. A newly created owner has zero
754	     * tenure, so the tenure bonus never applies on create.
755	     */
756	    private void assignMembership(Owner owner) {
757	        int points = 0;
758	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
759	            points += 2;
760	        }
761	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
762	            points += 1;
763	        }
764	        if (owner.getHouseholdMemberCount() != null && owner.getHouseholdMemberCount() >= 3) {
765	            points += 2;
766	        }
767	        if (tenureDays(owner) > TENURE_LEVEL_THRESHOLD_DAYS) {
768	            points += 3;
769	        }
770	        owner.setMembershipPoints(points);
771	        owner.setMembershipLevel(membershipLevelForPoints(points));
772	    }
773	
774	    /**
775	     * Maps {@code membershipPoints} to a {@code membershipLevel}: 1 for 0-1 points, 2 for 2-3, 3 for
776	     * 4-5, and 4 for 6 or more points.
777	     */
778	    private int membershipLevelForPoints(int points) {
779	        if (points <= 1) {
780	            return 1;
781	        }
782	        if (points <= 3) {
783	            return 2;
784	        }
785	        if (points <= 5) {
786	            return 3;
787	        }
788	        return 4;
789	    }
790	
791	    /**
792	     * The tenure, in days, of a newly created owner. Tenure accrues from membership over time, and a
793	     * new owner has not been a member for any elapsed time yet, so this is always {@code 0} on create
794	     * (regardless of any backdated {@code registrationDate}).
795	     */
796	    private long tenureDays(Owner owner) {
797	        return 0L;
798	    }
799	
800	    /**
801	     * Assigns the new owner's {@code bulkSignupWarning} on create: {@code true} when more than
802	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the new owner's adjusted
803	     * business-day {@code registrationDate}, otherwise {@code false}. Counted the same way as the
804	     * daily-limit rule and computed before the new owner is persisted, so it counts only the
805	     * pre-existing owners for that day.
806	     */
807	    private void assignBulkSignupWarning(Owner owner) {
808	        LocalDate registrationDate = owner.getRegistrationDate();
809	        int count = 0;
810	        for (Owner existing : this.clinicService.findAllOwners()) {
811	            if (registrationDate.equals(existing.getRegistrationDate())) {
812	                count++;
813	            }
814	        }
815	        owner.setBulkSignupWarning(count > BULK_SIGNUP_WARNING_THRESHOLD);
816	    }
817	
818	    /**
819	     * Assigns the new owner's {@code possibleDuplicate} / {@code possibleDuplicateOf} on create. The
820	     * owner has already cleared the duplicate block, so it is not a hard duplicate. It is flagged as a
821	     * possible duplicate when an existing owner shares its {@code lastName} (compared
822	     * case-insensitively) and its {@code postcode} (a present, exact match) while carrying a different
823	     * {@code telephone}. When such an owner exists, {@code possibleDuplicate} is set to {@code true}
824	     * and {@code possibleDuplicateOf} to that owner's id (the lowest id when several match); otherwise
825	     * {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf} is left {@code null}.
826	     * Computed before the new owner is persisted, so it considers only the pre-existing owners.
827	     *
828	     * <p>A declared household member ({@code sharesHousehold} set to {@code true}) is never flagged: it
829	     * has deliberately opted into an existing household, so its shared last name and postcode are
830	     * expected rather than a suspected duplicate.
831	     */
832	    private void assignPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
833	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
834	            owner.setPossibleDuplicate(false);
835	            owner.setPossibleDuplicateOf(null);
836	            return;
837	        }
838	        String lastName = owner.getLastName();
839	        String postcode = owner.getPostcode();
840	        String telephone = owner.getTelephone();
841	        Integer matchId = null;
842	        if (postcode != null) {
843	            for (Owner existing : this.clinicService.findAllOwners()) {
844	                if (lastName.equalsIgnoreCase(existing.getLastName())
845	                    && postcode.equals(existing.getPostcode())
846	                    && !postcode.isBlank()
847	                    && !java.util.Objects.equals(telephone, existing.getTelephone())
848	                    && existing.getId() != null
849	                    && (matchId == null || existing.getId() < matchId)) {
850	                    matchId = existing.getId();
851	                }
852	            }
853	        }
854	        owner.setPossibleDuplicate(matchId != null);
855	        owner.setPossibleDuplicateOf(matchId);
856	    }
857	
858	    /**
859	     * Computes the new owner's deterministic {@code householdId}: the first twelve upper-case hex
860	     * characters of the SHA-256 digest of {@code "<normalizedLastName>|<postcode>"}, where the last
861	     * name is normalized for comparison (trimmed, internal whitespace collapsed, lower-cased) and the
862	     * postcode is the already-validated 4-digit value. Because it is a pure function of the last name
863	     * and postcode, any two owners sharing those - regardless of creation order or whether they opted
864	     * into {@code sharesHousehold} - land in the same household automatically. Returns {@code null}
865	     * when the owner has no postcode, so such owners belong to no household. This single value feeds
866	     * both the duplicate detection ({@link #rejectDuplicate}) and the household-size count
867	     * ({@link #assignHouseholdMembership}).
868	     */
869	    private String computeHouseholdId(OwnerFieldsDto ownerFieldsDto) {
870	        String postcode = ownerFieldsDto.getPostcode();
871	        if (postcode == null || postcode.isBlank()) {
872	            return null;
873	        }
874	        String lastName = normalizeForComparison(ownerFieldsDto.getLastName());
875	        return shaHexUpper(lastName + "|" + postcode, 12);
876	    }
877	
878	    /**
879	     * Assigns the new owner's {@code householdMemberCount} on create: the number of owners sharing
880	     * the new owner's {@code householdId} once this create is applied — that is, the new owner plus
881	     * every existing owner already carrying the same identifier. Runs after the owner's
882	     * {@code householdId} has been set from {@link #computeHouseholdId} so the identifier is settled.
883	     * Left {@code null} when the owner belongs to no household.
884	     */
885	    private void assignHouseholdMembership(Owner owner) {
886	        String householdId = owner.getHouseholdId();
887	        if (householdId == null || householdId.isBlank()) {
888	            owner.setHouseholdMemberCount(null);
889	            return;
890	        }
891	        int count = 1;
892	        for (Owner existing : this.clinicService.findAllOwners()) {
893	            if (householdId.equals(existing.getHouseholdId())) {
894	                count++;
895	            }
896	        }
897	        owner.setHouseholdMemberCount(count);
898	    }
899	
900	    /**
901	     * Returns the first {@code length} characters of the SHA-256 digest of {@code input}, rendered as
902	     * upper-case hexadecimal. Used to derive the {@code customerCode} hash segment and the household
903	     * identifier, both stable functions of their inputs.
904	     */
905	    private static String shaHexUpper(String input, int length) {
906	        try {
907	            byte[] digest = MessageDigest.getInstance("SHA-256")
908	                .digest(input.getBytes(StandardCharsets.UTF_8));
909	            StringBuilder hex = new StringBuilder(digest.length * 2);
910	            for (byte b : digest) {
911	                hex.append(String.format("%02x", b));
912	            }
913	            return hex.substring(0, length).toUpperCase(Locale.ROOT);
914	        } catch (NoSuchAlgorithmException ex) {
915	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
916	        }
917	    }
918	}
